# Targeted raw-expression evidence, never BANKSY neighborhood features.
source(file.path(commandArgs(TRUE)[1],'code/common.R'))
if(file.exists(file.path(out,'supplement_complete.json')))quit(save='no')
old_section<-s%in%c('Cervilla','D1_Johnson');x<-load_extension(root,s,attach_results=TRUE);ids<-colnames(x[['RNA']]);md<-as.data.table(x[[]]);md[,bin_id:=ids];q<-LayerData(x,assay='RNA',layer='data');cts<-LayerData(x,assay='RNA',layer='counts');sym<-x[['RNA']][[]]$symbol
panels<-list(Keratin_extended=c('KRT14','KRT6A','KRT6B','KRT17','KRT5','COL17A1'),Urothelial_controls=c('EPCAM','KRT7','KRT19','UPK2'),Collagen_stroma=c('COL1A1','COL1A2','DCN','LUM'))
genes<-unlist(panels,use.names=FALSE);gm<-rbindlist(lapply(genes,function(g)data.table(symbol=g,feature_id=paste(rownames(q)[sym==g],collapse=';'),present=any(sym==g),matches=sum(sym==g))));fwrite(gm,file.path(out,'supplement_gene_coverage.tsv'),sep='\t')
# No sum of logged duplicate symbols: use raw summed counts and the unchanged bin total.
G<-sparseMatrix(i=match(sym[sym%in%genes],genes),j=which(sym%in%genes),x=1,dims=c(length(genes),length(sym)));raw<-as.matrix(G%*%cts);val<-log1p(sweep(raw,2,md$nCount_RNA,'/')*10000);rownames(raw)<-rownames(val)<-genes;colnames(raw)<-colnames(val)<-ids
supp<-data.table(bin_id=ids)
for(k in names(panels))supp[[paste0('ext_',k,'_detected')]]<-colSums(raw[panels[[k]],,drop=FALSE]>0)
supp[,ext_keratin_collagen_ge2:=ext_Keratin_extended_detected>=2&ext_Collagen_stroma_detected>=2];supp[,ext_controls_collagen_ge2:=ext_Urothelial_controls_detected>=2&ext_Collagen_stroma_detected>=2];supp[,ext_evidence_note:=fifelse(ext_keratin_collagen_ge2,'Multiple keratin and collagen genes detected; not proof of cellular admixture',fifelse(ext_Keratin_extended_detected>=2,'Multiple expanded keratin genes detected',fifelse(ext_Collagen_stroma_detected>=2,'Multiple collagen/stroma genes detected','Sparse selected-panel detection')))];fwrite(supp,file.path(out,'supplement_metadata.tsv.gz'),sep='\t')
for(k in setdiff(names(supp),'bin_id'))md[[k]]<-supp[[k]]
if(old_section){ro<-fread(file.path(old,s,'fixed_rois.tsv'));tr<-read_json(file.path(dirname(root),'hd_bin8_comparison_v1',s,'transform.json'),simplifyVector=TRUE);ro[,`:=`(x=(tr$fullres_crop_xyxy[1]+(x+.5)/tr$local_to_model_scale_xy[1]-.5)*tr$native_mpp,X=(tr$fullres_crop_xyxy[1]+(X+.5)/tr$local_to_model_scale_xy[1]-.5)*tr$native_mpp,y=(tr$fullres_crop_xyxy[2]+(y+.5)/tr$local_to_model_scale_xy[2]-.5)*tr$native_mpp,Y=(tr$fullres_crop_xyxy[2]+(Y+.5)/tr$local_to_model_scale_xy[2]-.5)*tr$native_mpp)]
 if(s=='D1_Johnson'){a<-md[,.(n=.N,agree=sum(singler_blca_pruned_labels=='Epithelial'&singler_hpca_pruned_labels=='Epithelial',na.rm=TRUE)),by=.(ix=floor(x_um/256),iy=floor(y_um/256))];a[,fraction:=agree/n];a<-a[n>=256][order(-agree,-fraction,ix,iy)];b<-a[1];ro<-rbind(ro,data.table(roi='reference_agree_control',x=b$ix*256,X=(b$ix+1)*256,y=b$iy*256,Y=(b$iy+1)*256,selection='Maximum pre-existing BLCA/HPCA epithelial agreement count in fixed 256um window; not histological purity'),fill=TRUE)}
 fwrite(ro,file.path(out,'fixed_rois.tsv'),sep='\t')
}else ro<-fread(file.path(out,'fixed_rois.tsv'))
groups<-list(l08=as.character(md$banksy_l08_cluster),reference=ifelse(md$singler_blca_pruned_labels=='Fibroblast'&md$singler_hpca_pruned_labels=='Epithelial','BLCA_Fib_HPCA_Epi',ifelse(md$singler_blca_pruned_labels=='Epithelial'&md$singler_hpca_pruned_labels=='Fibroblast','BLCA_Epi_HPCA_Fib',ifelse(md$singler_blca_pruned_labels==md$singler_hpca_pruned_labels,paste0('Agree_',md$singler_blca_pruned_labels),'Other'))));groups$reference[is.na(groups$reference)]<-'Not_both_evaluable'
stats<-list();add<-function(tag,group,ii){if(!length(ii))return();oo<-setdiff(seq_along(ids),ii);mu<-rowMeans(val[,ii,drop=FALSE]);av<-rowMeans(expm1(val[,ii,drop=FALSE]));avout<-if(length(oo))rowMeans(expm1(val[,oo,drop=FALSE])) else rep(NA_real_,length(genes));stats[[paste(tag,group)]]<<-data.table(context=tag,group=group,symbol=genes,n=length(ii),mean_log=mu,pct_positive=rowMeans(raw[,ii,drop=FALSE]>0),mean_normalized=av,log2_mean_effect=log2(1+av)-log2(1+avout))}
for(tag in names(groups))for(g in unique(groups[[tag]]))add(tag,g,which(groups[[tag]]==g))
for(i in seq_len(nrow(ro))){b<-ro[i];add('ROI',b$roi,which(md$x_um>=b$x&md$x_um<b$X&md$y_um>=b$y&md$y_um<b$Y))};fwrite(rbindlist(stats),file.path(out,'supplement_marker_statistics.tsv'),sep='\t')
# Tiny 14-gene visualization cache only (not whole normalized expression); released after plotting.
saveRDS(list(metadata=md[,intersect(names(md),c('bin_id','x_um','y_um','nCount_RNA','nFeature_RNA','banksy_l08_cluster','coarse_blca','coarse_hpca')),with=FALSE],log=val,panels=panels,rois=ro),file.path(out,'tmp/supplement_plot.rds'),compress=FALSE)
# Cross-section fixed denominators and information bands, no extra filtering.
md[,information_band:=cut(nFeature_RNA,c(-Inf,19,99,499,Inf),labels=c('<20','20-99','100-499','>=500'))];fwrite(md[,c('bin_id','nCount_RNA','nFeature_RNA','information_band','singler_blca_pruned_labels','singler_hpca_pruned_labels','coarse_blca','coarse_hpca','epi_fib_ge2',names(supp)[-1]),with=FALSE],file.path(out,'comparison_metadata.tsv.gz'),sep='\t')
write_json(list(n=length(ids),genes_requested=genes,missing=gm[present==FALSE,symbol],source='original RNA counts and LogNormalize; expanded panel kept separate from previous panel',old_region_labels_unchanged=TRUE),file.path(out,'supplement_complete.json'),auto_unbox=TRUE,pretty=TRUE);cat('SUPPLEMENT_COMPLETE',s,'\n')
